101	  <p class="empty" id="empty">Nothing here yet. Add your first todo above.</p>
102	</main>
103	<script src="todos.js"></script>
104	<script>
105	  var STORAGE_KEY = 'todos';
106	
107	  function makeId() {
108	    if (window.crypto && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
109	    return Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
110	  }
111	
112	  function load() {
113	    try {
114	      var data = JSON.parse(localStorage.getItem(STORAGE_KEY));
115	      return Array.isArray(data) ? data : [];
116	    } catch (e) {
117	      return [];
118	    }
119	  }
120	
121	  function save(todos) {
122	    try {
123	      localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
124	    } catch (e) {}
125	  }
126	
127	  var todos = load();
128	  var form = document.getElementById('todo-form');
129	  var input = form.querySelector('[data-testid="todo-input"]');
130	  var list = document.getElementById('todo-list');
131	  var empty = document.getElementById('empty');
132	  var dueInput = form.querySelector('[data-testid="todo-due"]');
133	  var priorityInput = form.querySelector('[data-testid="todo-priority"]');
134	  var filterButtons = document.querySelectorAll('#filters [data-filter]');
135	  var filter = 'all';
136	  var searchInput = document.querySelector('[data-testid="search-input"]');
137	  var search = '';
138	  var EMPTY_TEXT = {
139	    none: 'Nothing here yet. Add your first todo above.',
140	    active: 'All done. Nothing left to do.',
141	    completed: 'Nothing completed yet.',
142	    search: 'No todos match your search.'
143	  };
144	
145	  Array.prototype.forEach.call(filterButtons, function (button) {
146	    button.addEventListener('click', function () {
147	      filter = button.dataset.filter;
148	      render();
149	    });
150	  });
151	
152	  searchInput.addEventListener('input', function () {
153	    search = searchInput.value;
154	    render();
155	  });
156	
157	  // Swaps a todo's text for a field. Enter or blur saves; Escape discards.
158	  // An empty edit keeps the old text rather than deleting the todo.
159	  function startEdit(text, todo) {
160	    var field = document.createElement('input');
161	    field.type = 'text';
162	    field.className = 'edit';
163	    field.setAttribute('data-testid', 'todo-edit');
164	    field.setAttribute('aria-label', 'Edit "' + todo.text + '"');
165	    field.value = todo.text;
166	    var finished = false;
167	
168	    function finish(commit) {
169	      if (finished) return;
170	      finished = true;
171	      var value = field.value.trim();
172	      if (commit && value && value !== todo.text) {
173	        todos = todos.map(function (t) {
174	          return t.id === todo.id ? Object.assign({}, t, { text: value }) : t;
175	        });
176	        save(todos);
177	      }
178	      render();
179	    }
180	
181	    field.addEventListener('keydown', function (event) {
182	      if (event.isComposing) return;
183	      if (event.key === 'Enter') { event.preventDefault(); finish(true); }
184	      else if (event.key === 'Escape') { event.preventDefault(); finish(false); }
185	    });
186	    field.addEventListener('blur', function () { finish(true); });
187	
188	    text.replaceWith(field);
189	    field.focus();
190	    field.select();
191	  }
192	
193	  // Shows a stored "YYYY-MM-DD" as a local date, built from its parts so no UTC shift applies.
194	  function formatDue(due) {
195	    var parts = due.split('-');
196	    var date = new Date(Number(parts[0]), Number(parts[1]) - 1, Number(parts[2]));
197	    return date.toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' });
198	  }
199	
200	  function render() {
201	    var today = localDateString(new Date());
202	    Array.prototype.forEach.call(filterButtons, function (button) {
203	      button.setAttribute('aria-pressed', String(button.dataset.filter === filter));
204	    });
205	
206	    list.textContent = '';
207	    var shown = visibleTodos(todos, filter, search);
208	    shown.forEach(function (todo) {
209	      var completed = !!todo.completed;
210	      var li = document.createElement('li');
211	      li.setAttribute('data-testid', 'todo-item');
212	      li.setAttribute('data-completed', String(completed));
213	      var overdue = isOverdue(todo.due, today);
214	      li.setAttribute('data-overdue', String(overdue));
215	      li.setAttribute('data-priority', normalizePriority(todo.priority));
216	      li.dataset.id = todo.id;
217	
218	      var toggle = document.createElement('input');
219	      toggle.type = 'checkbox';
220	      toggle.className = 'toggle';
221	      toggle.setAttribute('data-testid', 'todo-toggle');
222	      toggle.setAttribute('aria-label', 'Mark "' + todo.text + '" as ' + (completed ? 'not done' : 'done'));
223	      toggle.checked = completed;
224	      toggle.addEventListener('change', function () {
225	        todos = todos.map(function (t) {
226	          return t.id === todo.id ? Object.assign({}, t, { completed: toggle.checked }) : t;
227	        });
228	        save(todos);
229	        render();
230	      });
231	
232	      var text = document.createElement('span');
233	      text.className = 'text';
234	      text.setAttribute('data-testid', 'todo-text');
235	      text.textContent = todo.text;
236	      text.addEventListener('dblclick', function () { startEdit(text, todo); });
237	
238	      var del = document.createElement('button');
239	      del.type = 'button';
240	      del.className = 'delete';
241	      del.setAttribute('data-testid', 'todo-delete');
242	      del.setAttribute('aria-label', 'Delete "' + todo.text + '"');
243	      del.textContent = 'Delete';
244	      del.addEventListener('click', function () {
245	        todos = todos.filter(function (t) { return t.id !== todo.id; });
246	        save(todos);
247	        render();
248	      });
249	
250	      li.appendChild(toggle);
251	      li.appendChild(text);
252	      if (typeof todo.due === 'string' && DUE_PATTERN.test(todo.due)) {
