270	    var todo = { id: makeId(), text: value, createdAt: Date.now(), completed: false, priority: normalizePriority(priorityInput.value) };
271	    if (DUE_PATTERN.test(dueInput.value)) todo.due = dueInput.value;
272	    todos.push(todo);
273	    save(todos);
274	    input.value = '';
275	    dueInput.value = '';
276	    priorityInput.value = 'med';
277	    input.focus();
278	    render();
279	  });
